  useCacheTimeout,
  staticPageGenerationTimeout,
  originalAppPath,
  isrFlushToDisk,
  cacheMaxMemorySize,
  nextConfigOutput,
  cacheHandler,
  cacheHandlers,
  cacheLifeProfiles,
  buildId,
  deploymentId,
  clientAssetToken,
  sriEnabled,
}: {
